                else { Log("TEXT_QST_028_GUILDMASTER_WILL_END_QUESTION_NO"); Log("MoveToGuildmasterMarker"); }
            }
        }
    }
};
static Guildmaster Make()
{
    Guildmaster g; std::memset(&g, 0, sizeof g);
